# Spec 134: overall survival in the bulk RNA-seq mesothelioma cohorts (Bueno, TCGA, MESOMICS; data and recipe as in bulk_analysis.R): the 68 tumour-selected TFs vs the other chromVAR TFs
#   per TF and cohort: Cox regression on expression (log2, per SD), stratified by histological subtype (as in bulk_analysis.R) and unstratified; fixed-effect meta-analysis over the three cohorts
#   A  strength of the association with survival (|meta z|), selected vs other TFs (Wilcoxon one-sided, selected larger)
#   B  share of TFs associated with survival (BH FDR < 0.05 over all TFs), by direction (Fisher)
#   C  the 68 TFs: meta hazard ratio per SD vs -log10 p
# env: SURV_MODEL = strata (default) | plain  -> which model the figure shows (both are in the table)
#      COHORTS = Bueno,TCGA,MESOMICS (default) -> cohorts in the meta-analysis; any other choice adds a suffix to the outputs (e.g. _Bueno_TCGA)
# needs: BULK_DIR (bulkRNA_meso), ARCHR_DIR
# outputs: spec134_TF_survival.csv, spec134_tests.csv, fig50_survival_selected_TFs.{png,pdf}
here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1])))
source(file.path(here, "repro_common.R")); source(file.path(here, "profiles.R")); source(file.path(here, "agree_common.R")); options(width = 220); suppressPackageStartupMessages(library(survival))
BD <- Sys.getenv("BULK_DIR", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/mesothelioma/scATAC_PM/bulkRNA_meso"); AR <- Sys.getenv("ARCHR_DIR", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/mesothelioma/scATAC_PM/tumor_compartment/scatac_ArchR"); MODEL <- Sys.getenv("SURV_MODEL", "strata")
fp <- function(p) ifelse(is.na(p), "n/a", ifelse(p < 0.001, formatC(p, format = "e", digits = 1), formatC(p, format = "g", digits = 2))); SC <- "#eb6834"
sel <- readRDS(file.path(AR, "selected_TF.rds")); suppressPackageStartupMessages(library(S4Vectors)); allTF <- union(unique(as.character(readRDS(file.path(AR, "TF_activators_genescore.rds"))$GeneScoreMatrix_name)), sel)
## cohorts, as in bulk_analysis.R
bm <- readRDS(file.path(BD, "bueno_meta_cli.rds")); bx <- readRDS(file.path(BD, "bueno_rpkm_cleaned.rds")); bx <- log2(as.matrix(bx[, rownames(bm)]) + 1); B <- data.frame(time = as.numeric(as.character(bm$Survival.from.surgery..years.)) * 12, status = as.integer(bm$Status == "d"), subtype = as.character(bm$ConsensusCluster), row.names = rownames(bm))
tm <- readRDS(file.path(BD, "meso_tcga_meta_cleaned.rds")); tx <- log2(as.matrix(readRDS(file.path(BD, "meso_tcga_RSEM_cleaned.rds"))) + 1); tm <- tm[tm$TUMOR_TYPE != "Diffuse Malignant Mesothelioma (NOS)", ]; tx <- tx[, rownames(tm)]; T <- data.frame(time = as.numeric(as.character(tm$OS_MONTHS)), status = as.integer(tm$DEATH_EVENT), subtype = as.character(tm$TUMOR_TYPE), row.names = rownames(tm))
mx <- as.matrix(readRDS(file.path(BD, "mesomics_data.rds"))); mm <- read.csv(file.path(BD, "mesomics_SamplesOverview.csv"), stringsAsFactors = FALSE); mm <- mm[match(colnames(mx), mm$Sample), ]; mx <- log2(mx + 1); M <- data.frame(time = as.numeric(as.character(mm$Survival.Time)), status = as.integer(mm$Survival.Censor == "dead"), subtype = as.character(mm$Type), row.names = colnames(mx))
CO <- list(Bueno = list(x = bx, m = B), TCGA = list(x = tx, m = T), MESOMICS = list(x = mx, m = M)); USE <- strsplit(Sys.getenv("COHORTS", "Bueno,TCGA,MESOMICS"), ",")[[1]]; stopifnot(all(USE %in% names(CO))); SFX <- if (length(USE) == 3) "" else paste0("_", paste(USE, collapse = "_")); CO <- CO[USE]; for (n in names(CO)) { ok <- !is.na(CO[[n]]$m$time) & !is.na(CO[[n]]$m$status) & CO[[n]]$m$time > 0 & !is.na(CO[[n]]$m$subtype); CO[[n]]$m <- CO[[n]]$m[ok, ]; CO[[n]]$x <- CO[[n]]$x[, ok]; cat(sprintf("%s: %d patients, %d deaths, time unit as given (median %.1f); subtypes: %s\n", n, sum(ok), sum(CO[[n]]$m$status), median(CO[[n]]$m$time), paste(names(table(CO[[n]]$m$subtype)), table(CO[[n]]$m$subtype), collapse = ", "))) }
tf <- Reduce(intersect, c(list(allTF), lapply(CO, function(c) rownames(c$x)))); tf <- tf[sapply(tf, function(g) all(sapply(CO, function(c) sd(c$x[g, ]) > 0 && mean(c$x[g, ] > 0) >= 0.2)))]; cat(sprintf("TFs in all cohorts used and detected in >= 20%% of tumours of each: %d of %d (selected: %d of %d)\n", length(tf), length(allTF), sum(tf %in% sel), length(sel)))
cox1 <- function(c, g, strat) { d <- c$m; d$e <- as.numeric(scale(c$x[g, ])); f <- suppressWarnings(coxph(if (strat) Surv(time, status) ~ e + strata(subtype) else Surv(time, status) ~ e, d)); s <- summary(f)$coefficients; c(beta = s[1, 1], se = s[1, 3]) }
meta <- function(b, s) { w <- 1 / s^2; be <- sum(w * b) / sum(w); se <- sqrt(1 / sum(w)); c(beta = be, se = se, z = be / se, p = 2 * pnorm(-abs(be / se))) }
RES <- do.call(rbind, lapply(tf, function(g) { o <- list(TF = g, selected = g %in% sel); for (md in c("strata", "plain")) { r <- sapply(CO, cox1, g = g, strat = md == "strata"); mt <- meta(r["beta", ], r["se", ]); for (n in names(CO)) { o[[sprintf("z_%s_%s", n, md)]] <- r["beta", n] / r["se", n] }; o[[paste0("HR_", md)]] <- exp(mt[["beta"]]); o[[paste0("z_", md)]] <- mt[["z"]]; o[[paste0("p_", md)]] <- mt[["p"]]; o[[paste0("n_same_dir_", md)]] <- max(sum(r["beta", ] > 0), sum(r["beta", ] < 0)) }; as.data.frame(o, stringsAsFactors = FALSE) }))
for (md in c("strata", "plain")) RES[[paste0("fdr_", md)]] <- p.adjust(RES[[paste0("p_", md)]], "BH"); RES <- RES[order(RES[[paste0("p_", MODEL)]]), ]; write.csv(RES, file.path(OUT, sprintf("spec134_TF_survival%s.csv", SFX)), row.names = FALSE)
TS <- do.call(rbind, lapply(c("strata", "plain"), function(md) { z <- RES[[paste0("z_", md)]]; fd <- RES[[paste0("fdr_", md)]]; s <- RES$selected; f <- function(a) { t <- table(factor(s, c(FALSE, TRUE)), factor(a, c(FALSE, TRUE))); fisher.test(t, alternative = "greater")$p.value }
  data.frame(model = md, n_selected = sum(s), n_other = sum(!s), median_absz_selected = median(abs(z[s])), median_absz_other = median(abs(z[!s])), p_absz = wilcox.test(abs(z[s]), abs(z[!s]), alternative = "greater")$p.value, median_z_selected = median(z[s]), median_z_other = median(z[!s]), p_z_two_sided = wilcox.test(z[s], z[!s])$p.value,
             pct_sig_selected = 100 * mean(fd[s] < 0.05), pct_sig_other = 100 * mean(fd[!s] < 0.05), p_sig = f(fd < 0.05), pct_worse_selected = 100 * mean(fd[s] < 0.05 & z[s] > 0), pct_worse_other = 100 * mean(fd[!s] < 0.05 & z[!s] > 0), p_worse = f(fd < 0.05 & z > 0), pct_better_selected = 100 * mean(fd[s] < 0.05 & z[s] < 0), pct_better_other = 100 * mean(fd[!s] < 0.05 & z[!s] < 0), p_better = f(fd < 0.05 & z < 0)) }))
write.csv(TS, file.path(OUT, sprintf("spec134_tests%s.csv", SFX)), row.names = FALSE); cat(sprintf("\nselected vs other TFs (meta-analysis over %s):\n", paste(USE, collapse = ", "))); print(t(TS), digits = 3, quote = FALSE)
for (n in names(CO)) for (md in c("strata", "plain")) { z <- RES[[sprintf("z_%s_%s", n, md)]]; cat(sprintf("  %s, %s: median |z| %.2f vs %.2f, p %s; nominal p<0.05: %.0f%% vs %.0f%%\n", n, md, median(abs(z[RES$selected])), median(abs(z[!RES$selected])), fp(wilcox.test(abs(z[RES$selected]), abs(z[!RES$selected]), alternative = "greater")$p.value), 100 * mean(abs(z[RES$selected]) > 1.96), 100 * mean(abs(z[!RES$selected]) > 1.96))) }
sh <- c("TF", paste0(c("HR_", "z_", "p_", "fdr_", "n_same_dir_"), MODEL), sprintf("z_%s_%s", names(CO), MODEL)); cat(sprintf("\nthe selected TFs associated with survival (model %s, FDR < 0.05):\n", MODEL)); print(RES[RES$selected & RES[[paste0("fdr_", MODEL)]] < 0.05, sh], digits = 2, row.names = FALSE)
cat("\nsame, other model:\n"); om <- setdiff(c("strata", "plain"), MODEL); x <- RES[RES$selected & RES[[paste0("fdr_", om)]] < 0.05, ]; print(x[order(x[[paste0("p_", om)]]), c("TF", paste0(c("HR_", "p_", "fdr_"), om))], digits = 2, row.names = FALSE)
z <- RES[[paste0("z_", MODEL)]]; fd <- RES[[paste0("fdr_", MODEL)]]; pv <- RES[[paste0("p_", MODEL)]]; hr <- RES[[paste0("HR_", MODEL)]]; s <- RES$selected; t1 <- TS[TS$model == MODEL, ]
spread <- function(y, gap) { o <- order(y); v <- y[o]; for (i in seq_along(v)[-1]) if (v[i] - v[i - 1] < gap) v[i] <- v[i - 1] + gap; y[o] <- v; y }
save_fig(paste0("fig50_survival_selected_TFs", SFX), 9.6, 3.6, function() {
  layout(t(1:3), widths = c(0.85, 0.75, 1.2)); par(family = "sans", mgp = c(2, 0.6, 0), tcl = -0.3); ttl <- function(x, y) { mtext(x, side = 3, adj = 0, line = 1.3, font = 2, cex = 0.72); mtext(y, side = 3, adj = 0, line = 0.35, cex = 0.5, col = INK2) }
  par(mar = c(3.4, 3.3, 2.8, 0.6)); L <- list(`68 selected TFs` = abs(z[s]), `other TFs` = abs(z[!s])); names(L)[1] <- sprintf("%d selected TFs", sum(s)); ym <- max(abs(z)); boxplot(L, col = c(adjustcolor(SC, 0.55), "#d5d4cf"), border = INK2, outline = FALSE, las = 1, ylab = "|z|, association with overall survival", cex.axis = 0.75, cex.lab = 0.8, ylim = c(0, ym * 1.14), lwd = 0.8); abline(h = 1.96, lty = 3, col = MUTED, lwd = 0.7)
  set.seed(1); points(jitter(rep(2, sum(!s)), 8), abs(z[!s]), pch = 16, cex = 0.35, col = adjustcolor("grey40", 0.5)); points(jitter(rep(1, sum(s)), 8), abs(z[s]), pch = 21, bg = SC, col = INK2, cex = 0.85, lwd = 0.6); yb <- ym * 1.04; segments(c(1, 1, 2), c(yb, yb - 0.02 * ym, yb - 0.02 * ym), c(2, 1, 2), c(yb, yb, yb), col = INK, lwd = 0.7); text(1.5, yb, sprintf("p = %s", fp(t1$p_absz)), pos = 3, cex = 0.7)
  ttl("A  strength of survival association", sprintf("meta-analysis of %s; one-sided Wilcoxon", paste(USE, collapse = " + ")))
  par(mar = c(3.4, 3.3, 2.8, 0.6)); TB <- rbind(c(t1$pct_worse_selected, t1$pct_better_selected), c(t1$pct_worse_other, t1$pct_better_other)); bp <- barplot(t(TB), col = c("#b2182b", "#2166ac"), border = "white", las = 1, names.arg = c("selected", "other TFs"), ylab = "% of TFs, FDR < 0.05", cex.axis = 0.75, cex.lab = 0.8, cex.names = 0.8, ylim = c(0, max(rowSums(TB)) * 1.45)); legend("topright", c("high = worse survival", "high = better survival"), fill = c("#b2182b", "#2166ac"), border = NA, bty = "n", cex = 0.62)
  text(bp, rowSums(TB), sprintf("%.0f%%", rowSums(TB)), pos = 3, cex = 0.7); ttl("B  share associated with survival", sprintf("Fisher: any p %s; worse p %s; better p %s", fp(t1$p_sig), fp(t1$p_worse), fp(t1$p_better)))
  par(mar = c(3.4, 3.3, 2.8, 0.6)); x <- log2(hr[s]); y <- -log10(pv[s]); f <- fd[s]; nm <- RES$TF[s]; plot(x, y, pch = 21, bg = ifelse(f < 0.05, ifelse(x > 0, "#b2182b", "#2166ac"), "grey80"), col = INK2, cex = 1.05, lwd = 0.6, bty = "n", las = 1, cex.axis = 0.75, cex.lab = 0.8, xlab = "log2 hazard ratio per SD of expression", ylab = "-log10 p", xlim = range(x) * 1.25); abline(v = 0, lty = 2, col = INK, lwd = 0.7)
  lb <- order(pv[s])[seq_len(min(14, sum(f < 0.05)))]; text(x[lb], y[lb], nm[lb], pos = ifelse(x[lb] > 0, 4, 2), cex = 0.58, xpd = NA); mtext("better survival", side = 1, adj = 0, line = 2.3, cex = 0.5, col = INK2); mtext("worse survival", side = 1, adj = 1, line = 2.3, cex = 0.5, col = INK2)
  ttl(sprintf("C  the %d selected TFs", sum(s)), sprintf("coloured = FDR < 0.05 over all %d TFs; Cox %s", nrow(RES), if (MODEL == "strata") "stratified by histology" else "unadjusted"))
})
